.pdm-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.pdm-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.pdm-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > div{background:linear-gradient(180deg,var(--wa-bg, #0d1117) 0%,var(--wa-bg, #111821) 100%)!important}
.pdm-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > img{opacity:.04!important;filter:invert(1)}
.pdm-root[data-theme="dark"] [data-name="Stage/3D Scene"] img{filter:brightness(.9) saturate(.95) contrast(1.03)}
.pdm-root[data-theme="dark"] [data-name="Stage/Building Image"] img{filter:brightness(.86) contrast(1.04)}
.pdm-root[data-theme="dark"] [data-name="Side Rail"],.pdm-root[data-theme="dark"] [data-name="Filter Panel"] [data-name="Rectangle 4"]{background:color-mix(in srgb, var(--wa-bg, rgb(20 23 29)) 84%, transparent)!important;box-shadow:0 0 0 1px rgba(255,255,255,.07),0 12px 28px rgba(0,0,0,.35)!important;-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
.pdm-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Background"],.pdm-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Header Background"]{background:var(--wa-bg, #12151b)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.07)!important}
.pdm-root[data-theme="dark"] svg [fill="#FCFCFC"]:not(mask *),.pdm-root[data-theme="dark"] svg [fill="#fcfcfc"]:not(mask *),.pdm-root[data-theme="dark"] svg [fill="white"]:not(mask *),.pdm-root[data-theme="dark"] svg [fill="#F9F9F9"]:not(mask *){fill:var(--wa-surface, #15181e)}
.pdm-root[data-theme="dark"] svg [stroke="#F1F1F1"]:not(mask *),.pdm-root[data-theme="dark"] svg [stroke="#f1f1f1"]:not(mask *),.pdm-root[data-theme="dark"] svg [fill="#F1F1F1"]:not(mask *){stroke:var(--wa-line, #2a2e36)}
.pdm-root[data-theme="dark"] svg path[fill="#F1F1F1"]:not(mask *){fill:var(--wa-surface, #2a2e36)}
.pdm-root[data-theme="dark"] [data-name="Event Log"] [data-name^="Row/"]:hover,.pdm-root[data-theme="dark"] [data-name="Event Log"] [data-name="grid-row"]:hover{filter:brightness(1.15)}
